<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Checkout signed</title><style>body{font-family:Arial;background:#f1f7ef;color:#234222;margin:0;padding:24px}.card{max-width:560px;margin:10vh auto;background:white;border:1px solid #d8e7d4;border-radius:22px;padding:30px;text-align:center}h1{color:#347b31}</style></head><body><div class="card"><h1>{{ session('status') === 'test' ? 'Test signature submitted' : 'Checkout signed successfully' }}</h1><p>{{ session('status') === 'test' ? 'The signature interaction worked. No asset or assignment was changed.' : 'Your digital signature has been recorded. The asset checkout is now complete.' }}</p><p>You may close this page.</p></div></body></html>
